import{z as o,x as A,o as n,c as p,q as t,j as i,D as E,d as r,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"股票回购","description":"","frontmatter":{"title":"股票回购","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/share-repurchase.md","filePath":"econ/share-repurchase.md","lastUpdated":1791063341000}'),d={name:"econ/share-repurchase.md"};function m(h,a,C,D,c,u){const l=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="股票回购" tabindex="-1">股票回购 <a class="header-anchor" href="#股票回购" aria-label="Permalink to &quot;股票回购&quot;">​</a></h1><div class="epigraph"><p>回购与现金股利在无摩擦世界里同是把现金交给股东；有税、有信号、有灵活度时，二者不再是同一张支票。</p><footer>—— 据 MM 1961 的支付无关；对照 Comment and Jarrell, The Relative Signalling Power of Dutch-Auction and Fixed-Price Self-Tender Offers and Open-Market Share Repurchases, Journal of Finance, 1991</footer></div><p><a href="/econ/dividend-signaling">上一课</a>把派息写成昂贵信号或盈余推断。若信号必须烧现金，回购也能烧。本课缺口是替代：何时用回购代替股利，信号强度是否相同。不重做 Bhattacharya 的分离，不把回购当成微观结构上的买卖。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MM 1961：投资给定，现金股利与回购都只是资产换成现金，股东自制可得。引入税与信息之后，回购常被当作「更灵活的股利」：没有 Lintner 式的下调惩罚，资本利得税往往低于股利税，并且可以向未出售的股东做隐式选择。缺口是：灵活是否同时削弱信号？Comment 与 Jarrell（1991）给一句对照：固定价格与荷兰式要约回购的信号，强于公开市场回购——承诺更硬、折价更明确的，说话更响。</p><p>本课不把这句话做成事件研究表。只要钉：替代不是完全的，形式携带承诺硬度。</p><p><span class="marginnote">公开市场回购是授权后相机买回，可撤。要约回购在窗口内以指定价格（或荷兰式区间）买固定数量，更接近一次性昂贵行动。</span></p><p><span class="marginnote">术语翻译：「荷兰式拍卖回购」就是公司公布一个价格区间、让股东报价、再从低往高找出能买满目标数量所需最低价的手段来做一次性大额回购的事——像一场反向的减价拍卖，报价越低越先成交，成交价把「愿意卖的人的底线」暴露得很清楚，所以承诺更硬。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先保留无关性基准：同一现金离开企业，总价值在无摩擦时不变，只改股份数与每股。再放进三块摩擦。税：回购把应税事件推到卖出时点。代理：回购与股利一样降低 FCF，但经理可把授权当储备、不执行。信号：上一课的分离要求成本；公开市场回购的成本是软的，要约回购更接近股利承诺。</p>',10)),(n(),i(B,null,{default:E(()=>[s(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASH%5B%22%E7%8E%B0%E9%87%91%E7%A6%BB%E5%BC%80%E4%BC%81%E4%B8%9A%22%5D%20--%3E%20MM%5B%22%E6%97%A0%E6%91%A9%E6%93%A6%3A%20%E4%B8%8E%E8%82%A1%E5%88%A9%E7%AD%89%E4%BB%B7%22%5D%0A%20%20CASH%20--%3E%20TAX%5B%22%E7%A8%8E%E4%B8%8E%E7%81%B5%E6%B4%BB%E5%BA%A6%22%5D%0A%20%20CASH%20--%3E%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E7%A1%AC%E5%BA%A6%22%5D%0A%20%20SIG%20--%3E%20OM%5B%22%E5%85%AC%E5%BC%80%E5%B8%82%E5%9C%BA%3A%20%E8%BD%AF%22%5D%0A%20%20SIG%20--%3E%20TO%5B%22%E8%A6%81%E7%BA%A6%20%2F%20%E8%8D%B7%E5%85%B0%E5%BC%8F%3A%20%E6%9B%B4%E7%A1%AC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"优序：回购常发生在经理认为股份被低估时，与发股的柠檬对称。这与信号一致，但不要把每一笔授权都叫成分离均衡——授权可以是期权，执行才是行动。",-1)),a[4]||(a[4]=e("h3",{id:"一句对照-不审表",tabindex:"-1"},[r("一句对照，不审表 "),e("a",{class:"header-anchor",href:"#一句对照-不审表","aria-label":'Permalink to "一句对照，不审表"'},"​")],-1)),a[5]||(a[5]=e("p",null,"Comment–Jarrell：荷兰式与固定价格自要约的公告反应，大于公开市场回购。本课用它标明「硬度梯度」，不报告百分点，不把样本写成定理。后文若要超额与异常收益，换量化栏或事件研究课，本栏不到限价簿上数买盘。",-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"机制是支付形式选择。股利把同一每股现金给所有人，下调有历史锚。回购让边际股东自我选择卖出，留下的股东提高份额；经理对价格的判断（低估才买）同时泄漏信息。要约把价格写进合同，模仿成本更高，于是更像 Bhattacharya 的贵行动。公开市场把行动拆成许多天的相机购买，差类型更容易假装。",-1)),(n(),i(B,null,{default:E(()=>[s(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E5%BE%85%E5%88%86%E9%85%8D%E7%8E%B0%E9%87%91%22%5D%20--%3E%20DIV%5B%22%E8%82%A1%E5%88%A9%E5%BD%A2%E5%BC%8F%22%5D%0A%20%20POOL%20--%3E%20BUY%5B%22%E5%9B%9E%E8%B4%AD%E5%BD%A2%E5%BC%8F%22%5D%0A%20%20DIV%20--%3E%20ALL%5B%22%E6%89%80%E6%9C%89%E8%82%A1%E4%B8%9C%E6%8C%89%E6%8C%81%E8%82%A1%E6%AF%94%E4%BE%8B%E9%A2%86%E7%8E%B0%E9%87%91%22%5D%0A%20%20DIV%20--%3E%20PAIN%5B%22%E4%B8%8B%E8%B0%83%E8%82%A1%E5%88%A9%E6%9C%89%E5%8E%86%E5%8F%B2%E9%94%9A%E6%83%A9%E7%BD%9A%22%5D%0A%20%20BUY%20--%3E%20SEL%5B%22%E6%83%B3%E8%B5%B0%E7%9A%84%E8%82%A1%E4%B8%9C%E8%87%AA%E6%88%91%E9%80%89%E6%8B%A9%E5%8D%96%E5%87%BA%22%5D%0A%20%20BUY%20--%3E%20STAY%5B%22%E7%95%99%E5%AE%88%E8%82%A1%E4%B8%9C%E4%BB%BD%E9%A2%9D%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BUY%20--%3E%20SOFT%5B%22%E5%85%AC%E5%BC%80%E5%B8%82%E5%9C%BA%E6%8E%88%E6%9D%83%E5%8F%AF%E6%8B%96%E5%8F%AF%E6%92%A4%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p><span class="marginnote">数字实例：公司 1 亿元利润、100 万股，EPS 是 100 元；花 2000 万元按每股 100 元买回 20 万股后，利润没变、只剩 80 万股，EPS 变成 125 元，机械上涨 25%——公司一分钱没多赚，涨的只是每股口径。</span></p><p>Jensen 的 FCF 两条都能吐现金；Lintner 平滑主要绑在股利上，这正是成熟企业并行使用两种工具的理由：用股利说持久，用回购说暂时多余。不要把并行写成「投资者非理性地喜欢股利」。</p><p><span class="marginnote">回购减少股份，每股盈利机械上升。那不是价值创造。价值在于现金离开与信息，不在于 EPS 算术。</span></p><p><span class="marginnote">常见误区：初学者容易以为回购必然抬高股价、创造价值。实际上 MM 基准下股东财富不变——卖出的股东拿走现金，留下的股东持股变值钱，两头的总和还是原来的数。真正的价值差异只能来自税差、信号与代理，而不是「回购」这个动作本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在本栏做回购异象或长期弱势。不要把公开市场回购写成在限价簿上吃卖盘的执行算法——那是量化栏。下一课 <a href="/econ/convertible-security">可转债</a>换融资工具：不是把现金吐出，而是把债做成后门权益。</p><p>后课默认：回购在 MM 下与股利等价；税、灵活度与承诺硬度使它们成为不完全替代。Comment–Jarrell 标明要约比公开市场更像信号。</p><p>内幕期间买回受管制约束，本课不写合规清单。强式失败仍是经理信息的前提。</p><p>加速摊薄的期权、员工持股，会使经理更喜欢回购而不是股利——那是激励合同，不是 MM 的支付无关被否证。本课不把补偿设计写成主线。</p><p>可转债下一课换融资侧：现金进来而不是出去。支付形式与证券设计是公司金融里对称的两块摩擦。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无摩擦时回购与现金股利同为支付；摩擦下二者不完全替代。</li><li>公开市场软，要约与荷兰式更硬；Comment–Jarrell 用公告反应对照这一句。</li><li>代理吐出现金与信号揭示低估可以并存，EPS 机械上升不是机制。</li><li>本课不把公开市场回购写成在限价簿上吃卖盘。</li><li>下一课可转债换融资工具：后门权益，不是把现金吐出。</li><li>出处：Miller and Modigliani 1961 的支付基准；Comment and Jarrell, <em>JF</em> 1991。</li></ul>',12))])}const P=o(d,[["render",m]]);export{S as __pageData,P as default};
